from pathlib import Path
import json,sys,time
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT))
from scripts.agy_pipeline import invoke
OUT=ROOT/'reports/drama-A1-all-20261001';M=json.loads((OUT/'manifest.json').read_text())
start=int(sys.argv[1]);count=int(sys.argv[2]);items=M[start:start+count]
key=f'{start:03}-{start+len(items)-1:03}';folder=OUT/'narration-attempts'/key;folder.mkdir(parents=True,exist_ok=True)
assert not (folder/'attempt.json').exists(),'Do not repeat a submitted/unreconciled authoring attempt'
schema={'type':'object','properties':{'episodes':{'type':'array','minItems':len(items),'maxItems':len(items),'items':{'type':'object','properties':{'job':{'type':'string'},'title':{'type':'string'},'plot_vi':{'type':'string'},'opening_function_vi':{'type':'string'},'learner_outcome_vi':{'type':'string'},'characters':{'type':'array','items':{'type':'object','properties':{'id':{'type':'string'},'name_vi':{'type':'string'},'appearance_en':{'type':'string'},'outfit_en':{'type':'string'}},'required':['id','name_vi','appearance_en','outfit_en'],'additionalProperties':False}},'scenes':{'type':'array','items':{'type':'object','properties':{'scene_id':{'type':'string'},'title_vi':{'type':'string'},'narration':{'type':'string'},'purpose_en':{'type':'string'},'visual_en':{'type':'string'},'character_ids':{'type':'array','items':{'type':'string'}},'practice_pause_seconds':{'type':'number'}},'required':['scene_id','title_vi','narration','purpose_en','visual_en','character_ids','practice_pause_seconds'],'additionalProperties':False}}},'required':['job','title','plot_vi','opening_function_vi','learner_outcome_vi','characters','scenes'],'additionalProperties':False}}},'required':['episodes'],'additionalProperties':False}
inputs=[{'job':e['job'],'word':e['word'],'pos':e['pos'],'gloss_vi':e.get('selected_gloss_vi',e['gloss_vi']),'entry_id':e['entry_id'],'scene_count':e['scene_count'],'required_points':e['brief']['required_points'],'avoid_other_senses':e['brief']['planning']['avoid']} for e in items]
sample=json.loads((ROOT/'reports/drama-A1-pilot-20261001/authoring/loi-dan-da-chot.json').read_text())
prompt='''You are the approved vocabulary content authoring tool. Return only the JSON object; never call tools, edit files, create jobs, approve anything, or generate media. Preserve all supplied Vietnamese data and English teaching sentences. We need ORIGINAL Vietnamese short-film narration, not five-part lessons disguised as stories. The user approved a short emotional departure story as the desired FORMAT and now requests all remaining A1 scripts. Use that level of concrete action, ordinary speech, emotion and a payoff. Do not copy its mother/bus/two-cup story. Choose different relationships, settings, stakes and opening functions across these episodes. Film comes first, English is needed by the characters. Do not write "X là ...", "Ví dụ thứ nhất", "Đến lượt bạn thực hành", "Bạn nhớ rất tốt", or a stock motivational lesson ending. Include necessary Vietnamese meaning naturally in dialogue/action. First sentence has at most nine whitespace units, starts with a specific interesting action, contradiction, need or inner thought, with no greeting/title introduction. Show enough immediate context so a beginner understands. Get the first usable English model early, preferably scene one or the opening of scene two. Every episode teaches only the bank sense provided; retain all required learning points and exactly the supplied scene count. Include the required number of correct simple English models, spoken in quotation marks with clear punctuation and Vietnamese support. Use I correctly. Later scenes must change the causal situation; do not just list examples or summarize definitions. A manageable listener retrieval turn should be tied to the character's need, have a three-to-five-second pause at its scene END, and get a correct response in the NEXT scene before an emotional/concrete ending. The last scene resolves the local opening promise. Put incomplete stems in later visual plans, NOT in narration: never speak a phrase containing ... because it breaks subtitles. Do not insert production instructions or seconds into spoken text. Aim roughly 130–175 Vietnamese whitespace units including English utterances total, flexible for five/seven scenes and difficult words; do not pad or omit required ideas. Frame directions and purposes are English, spoken story and descriptions for user are Vietnamese. A main character is always CH01, the same canonical mascot in exactly one pale-blue short-sleeve shirt, a round white navy-outlined head, solid black oval eyes and minimal stick limbs. It may be a friend, employee, family member etc. Keep its core identity; gestures/expressions can vary. Add only essential secondary characters and maintain their appearances/outfits per episode. Character codes may appear only in metadata, not visual prose. Invented ordinary stories are fiction, not factual claims about real people. No new linguistic etymology/pronunciation claims. Different episodes must differ in plot and opening, not just substitute a noun in a template. Do NOT create anchors/coverage yet: write narration first for freezing and human editorial review. This is an authoring batch, no workflow actions or quality approval.\n'''
prompt+='\nEditorial corrections from the first authored batch: use plain conversational Vietnamese like the approved sample, never tinh khoi, trang trong ngu, vet sang am ap, hay tu tin, ban nho rat tot. No orphan/valedictorian backstory, naval rank, precise millimetre/glass cutting claims, or unsupported material guarantees such as an eraser never tearing paper. Show a small believable relationship or choice and an ordinary concrete ending. Do not convert every close into a generic poetic departure. Prefer one simple supported FULL English sentence as learner retrieval with feedback, rather than only naming a word. Keep the first English utterance near the first short opening, avoiding long backstory before it. Describe secondary people as minimal ink stick figures too, with one plain role-specific outfit; no realistic detailed fingers or muscles. Their actual emotions can be modest. Visual prose should name the specific static state/action, not refer to unspecified on-screen practice indicators.'
prompt+='\nAdditional strict craft constraints: every episode needs believable everyday dialogue and a real relational choice, not a countdown industrial procedure. Do not teach solar electricity, motor repair, cooking ratios, crop prices, health claims or machinery steps. Keep technical activity as background only. Do not change a previously selected computer-file sense into a paper medical folder. For a short request example spoken directly to someone, match speaker and addressee. Keep scenes simple enough for a static minimal stick-figure frame and avoid unspecified crowds. A normal imperfect result is preferable to a grand miraculous success.'
prompt+='\nApproved format sample (quality reference; do not reuse its plot): '+json.dumps(sample,ensure_ascii=False)
prompt+='\nEpisodes required, exact jobs and scene counts: '+json.dumps(inputs,ensure_ascii=False)
(folder/'prompt.txt').write_text(prompt);(folder/'schema.json').write_text(json.dumps(schema,ensure_ascii=False,indent=2)+'\n');(folder/'attempt.json').write_text(json.dumps({'state':'submitted','jobs':[e['job'] for e in items],'started_at':time.time()},indent=2)+'\n')
try:
 result=invoke(prompt,schema,folder,timeout=900);(folder/'response.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');data=result['structured_output'];assert {x['job'] for x in data['episodes']}=={e['job'] for e in items}
 for ep in data['episodes']:
  e=next(e for e in items if e['job']==ep['job']);assert [s['scene_id'] for s in ep['scenes']]==[f'SC{i:02}' for i in range(1,e['scene_count']+1)];assert all('...' not in s['narration'] and '…' not in s['narration'] for s in ep['scenes']);assert any(s['practice_pause_seconds']>0 for s in ep['scenes'][:-1]);assert ep['scenes'][-1]['practice_pause_seconds']==0
 (folder/'episodes.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');(folder/'attempt.json').write_text(json.dumps({'state':'authored_not_reviewed','jobs':[e['job'] for e in items],'completed_at':time.time()},indent=2)+'\n');print('AUTHORED',key,len(items),'episodes, awaiting actual editorial review',flush=True)
except Exception as ex:
 (folder/'attempt.json').write_text(json.dumps({'state':'blocked','error':str(ex),'jobs':[e['job'] for e in items]},ensure_ascii=False,indent=2)+'\n')
 with (ROOT/'logs/issues/ISSUE-DRAMA-A1-ALL-20261001.md').open('a') as f:f.write('\n## Authoring batch '+key+' failed\n\n'+str(ex)+'\n\nNo automatic retry, paid API or provider switch; retain attempt and inspect actual response.\n')
 raise
